      "edit_info" : {
        "initial" : {
          "editTweetIds" : [
            "1080909441786994688"
          ],
          "editableUntil" : "2019-01-03T20:31:07.905Z",
          "editsRemaining" : "5",
          "isEditEligible" : true
        }
      },
      "retweeted" : false,
      "source" : "<a href=\"http://twitter.com\" rel=\"nofollow\">Twitter Web Client</a>",
